// Expéditeur · Envoi des pré-audits (refait le 14/10/2026 ; source : n8n/expediteur_envoi.json du dépôt raime-cerveau).
// pause : rien ne part ; test : tout part vers l'adresse de test (marqué « teste », jamais compté comme un envoi) ;
// live : vers le prospect, les jours ouvrés seulement. Les e-mails viennent de la vue envoi_preaudits (n8n/envois.sql), déjà
// coupée au plafond du jour : les brouillons écrits par le code partent seuls (Basile, 14/10/2026 : « je ne veux plus valider »).
// Le lien du pré-audit doit répondre (un PDF) avant que l'e-mail parte : lien mort, l'e-mail attend le lendemain.
const cfg = ($('Lire config').first() || { json: {} }).json || {};
const mode = cfg.mode || 'pause';
if (mode !== 'live' && mode !== 'test') return [];
const jour = new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris', weekday: 'short' });
if (mode === 'live' && (jour === 'Sat' || jour === 'Sun')) return [];
if (mode === 'test' && !cfg.test_to) return [];
const plafond = Math.max(0, parseInt(cfg.plafond, 10) || 0);
const fromEmail = cfg.from_email || 'contact@raime.fr';
const fromName = cfg.from_name || 'Basile Ramé';
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const liens = (s) => s.replace(/https:\/\/[^\s<]+/g, (u) => '<a href="' + u + '">' + u + '</a>');
const NL = String.fromCharCode(10);
const LIEN = /https:\/\/raime\.fr\/dossiers\/rAIme-pre-audit-[a-z0-9-]+\.pdf/;
const vus = {};
const pdfVivant = async (url) => {
  if (!(url in vus)) {
    try {
      const r = await this.helpers.httpRequest({ method: 'HEAD', url, returnFullResponse: true, timeout: 15000 });
      vus[url] = r.statusCode === 200 && /pdf/i.test(String((r.headers || {})['content-type'] || ''));
    } catch (e) { vus[url] = false; }
  }
  return vus[url];
};
const signature = '<div style="margin-top:20px;padding-top:14px;border-top:1px solid #eee"><table style="border-collapse:collapse"><tr>'
  + '<td style="vertical-align:middle;padding-right:11px"><div style="width:36px;height:36px;border-radius:9px;background:#10b981;color:#ffffff;font-weight:700;font-size:21px;font-family:Georgia,serif;font-style:italic;text-align:center;line-height:36px">r</div></td>'
  + '<td style="vertical-align:middle"><div style="font-weight:700;font-size:14px;color:#111">Basile Ramé · rAIme</div>'
  + '<div style="font-size:12px;color:#8a8a8a">Conseil · Formation · Automatisation IA — <a href="https://raime.fr" style="color:#10b981;text-decoration:none">raime.fr</a></div></td></tr></table></div>';
const out = [];
for (const it of $('A envoyer').all()) {
  if (out.length >= plafond) break;
  const d = it.json || {};
  if (!d.id || !d.to_email || !d.body) continue;
  const lien = (String(d.body).match(LIEN) || [])[0];
  if (d.status === 'brouillon' && !lien) continue;
  if (lien && !(await pdfVivant(lien))) continue;
  const desinscription = 'https://cockpit.raime.fr/unsub?e=' + encodeURIComponent(d.to_email);
  const essai = mode === 'test' ? ' · [ESSAI : destinataire réel ' + esc(d.to_email) + ']' : '';
  const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14.5px;line-height:1.6;color:#1a1a1a">'
    + liens(esc(d.body)).split(NL).join('<br>') + signature
    + '<p style="font-size:11px;color:#aaaaaa;margin-top:16px">' + esc(fromEmail) + essai
    + ' · <a href="' + desinscription + '" style="color:#aaaaaa">se désinscrire</a></p></div>';
  out.push({ json: { id: d.id, mode, email_body: {
    from: fromName + ' <' + fromEmail + '>',
    to: [mode === 'live' ? d.to_email : cfg.test_to],
    reply_to: fromEmail,
    subject: (mode === 'test' ? '[ESSAI] ' : '') + (d.subject || 'rAIme'),
    html,
    text: d.body + NL + NL + 'Se désinscrire : ' + desinscription,
    headers: { 'List-Unsubscribe': '<' + desinscription + '>' },
  } } });
}
return out;

// Chaque e-mail est marqué selon SA réponse de Resend (14/10/2026). Le 12, le 13 et le 14/10, l'ancien Expéditeur marquait
// « envoyé » les 18 du jour alors que Resend en refusait 8 (429, envoyés tous ensemble) : 24 e-mails jamais partis.
// Resend n'a rien pris (429 : trop vite ou quota ; 5xx) : l'e-mail reste dans la file, il repart au passage suivant.
// Une panne sans réponse (délai dépassé) est inconnue : peut-être parti ; marqué « erreur », jamais renvoyé (pas de doublon).
const envois = $('Prepare').all();
const reponses = $input.all();
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const lignes = [];
envois.forEach((e, i) => {
  const id = parseInt(e.json.id, 10);
  if (isNaN(id)) return;
  const r = (reponses[i] || { json: {} }).json || {};
  const ok = typeof r.id === 'string' && /^[A-Za-z0-9-]{8,64}$/.test(r.id) && !r.statusCode && !r.error;
  const code = Number(r.statusCode || (r.error && (r.error.httpCode || r.error.status))) || (/\b429\b/.test(JSON.stringify(r.error || '')) ? 429 : 0);
  const reessai = !ok && (code === 429 || code >= 500);
  const statut = ok ? (e.json.mode === 'live' ? 'envoye' : 'teste') : (reessai ? null : 'erreur');
  const erreur = ok ? null : String(r.message || (r.error && (r.error.message || r.error)) || 'réponse inattendue de Resend').slice(0, 200);
  lignes.push('(' + id + ',' + (statut ? q(statut) : 'NULL') + ',' + (ok ? q(r.id) : 'NULL') + ',' + (erreur === null ? 'NULL' : q(erreur)) + ')');
});
if (!lignes.length) return [];
const sql = 'UPDATE outreach o SET status = coalesce(v.statut::text, o.status), resend_id = coalesce(v.resend_id::text, o.resend_id), '
  + "erreur = v.erreur::text, sent_at = CASE WHEN v.statut::text = 'envoye' THEN now() ELSE o.sent_at END "
  + 'FROM (VALUES ' + lignes.join(',') + ") AS v(id, statut, resend_id, erreur) WHERE o.id = v.id AND o.sent_at IS NULL AND o.status IN ('valide', 'brouillon');";
return [{ json: { sql, count: lignes.length } }];

// L'état de livraison annoncé par Resend (delivered, bounced, complained…) revient dans la ligne (14/10/2026) : le plafond
// (plafond_envoi, n8n/envois.sql) redescend au départ quand les e-mails reviennent ; le rapport de 7 h 30 en donne les chiffres.
const demandes = $('Livraison a verifier').all();
const reponses = $input.all();
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const par = { outreach: [], vitrines_envoi: [] };
demandes.forEach((d, i) => {
  const t = d.json.t, id = parseInt(d.json.id, 10);
  const r = (reponses[i] || { json: {} }).json || {};
  const etat = String(r.last_event || '');
  if (!par[t] || isNaN(id) || r.id !== d.json.resend_id || !/^[a-z_]{3,30}$/.test(etat)) return;
  par[t].push('(' + id + ',' + q(etat) + ')');
});
const sql = Object.entries(par).filter(([, l]) => l.length)
  .map(([t, l]) => 'UPDATE ' + t + ' x SET livraison = v.etat::text FROM (VALUES ' + l.join(',') + ') AS v(id, etat) WHERE x.id = v.id;').join(' ');
return sql ? [{ json: { sql } }] : [];
